cases.policy:
// R16g planted cap (cap-request-to-response)
@id("cap_cap_request_to_response")
permit (
    principal,
    action == Bank::Action::"Pay",
    resource
)
when temporal { sum_within(a, 24h, Bank::Action::"Pay"::response{ input.amount: a }) - sum_within(a, 24h, Bank::Action::"Pay"::refund{ input.amount: a }) <= 100 };

